// ─── File: src/test/java/com/bank/worksteal/WorkStealingTest.java ───
package com.bank.worksteal;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class WorkStealingTest {

    // ═══ Work-stealing keeps all cores busy ═══
    @Test
    void workStealing_allCoresBusy() {
        ForkJoinPool pool = new ForkJoinPool(4);
        AtomicInteger tasksProcessed = new AtomicInteger(0);

        pool.invoke(new RecursiveAction() {
            @Override protected void compute() {
                RecursiveAction[] subtasks = new RecursiveAction[20];
                for (int i = 0; i < 20; i++) {
                    subtasks[i] = new RecursiveAction() {
                        @Override protected void compute() {
                            long sum = 0;
                            for (int j = 0; j < 1_000_000; j++) sum += j;
                            tasksProcessed.incrementAndGet();
                        }
                    };
                }
                invokeAll(subtasks);
            }
        });

        assertThat(tasksProcessed.get()).isEqualTo(20);
        System.out.println("Steal count: " + pool.getStealCount());
        assertThat(pool.getStealCount()).isGreaterThan(0);  // work was stolen!
        pool.shutdown();
    }

    // ═══ Blocking IO on common pool: stalls parallelStream ═══
    @Test
    void blockingCommonPool_stallsParallelStream() throws InterruptedException {
        int parallelism = ForkJoinPool.commonPool().getParallelism();

        // Block all common pool workers:
        for (int i = 0; i < parallelism; i++) {
            CompletableFuture.runAsync(() -> {
                try { Thread.sleep(2000); } catch (InterruptedException e) { }
            });  // default = common pool! Blocks workers!
        }
        Thread.sleep(100);

        // parallelStream on common pool → starved!
        long start = System.currentTimeMillis();
        long sum = LongStream.range(0, 100).parallel().sum();
        long elapsed = System.currentTimeMillis() - start;

        System.out.println("parallelStream during blocking: " + elapsed + "ms");
        // May be slow! Workers occupied by IO!
    }

    // ═══ Dedicated pool: no starvation ═══
    @Test
    void dedicatedPool_noStarvation() throws InterruptedException {
        ExecutorService ioPool = Executors.newFixedThreadPool(10);

        // IO on dedicated pool:
        for (int i = 0; i < 10; i++) {
            CompletableFuture.runAsync(() -> {
                try { Thread.sleep(500); } catch (InterruptedException e) { }
            }, ioPool);  // dedicated!
        }

        // parallelStream on common pool — NOT starved!
        long start = System.currentTimeMillis();
        long sum = LongStream.range(0, 1_000_000).parallel()
            .map(x -> x * x).sum();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isLessThan(500);  // fast! Common pool free!
        ioPool.shutdown();
    }

    // ═══ getStealCount shows work-stealing activity ═══
    @Test
    void stealCount_showsActivity() {
        ForkJoinPool pool = new ForkJoinPool(2);
        IntStream.range(0, 1000).parallel().forEach(i -> {
            long sum = 0;
            for (int j = 0; j < 10000; j++) sum += j;
        });

        System.out.println("Common pool steal count: " + ForkJoinPool.commonPool().getStealCount());
    }
}
